<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\DB;use App\Core\Mailer;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\License;use App\Models\Plan;use App\Models\User;use App\Services\LicenseService;final class LicenseController extends AdminController{public function index(Request $s):Response{$A=License::query()->select('t.*, u.email AS user_email, p.slug AS plan_slug')->join('JOIN '.DB::q(DB::table('users')).' u ON u.id = t.user_id')->join('JOIN '.DB::q(DB::table('plans')).' p ON p.id = t.plan_id')->orderBy('t.id','DESC');if($s->str('status')){$A->where('t.status',$s->str('status'));}if($s->str('plan')){$A->where('p.slug',$s->str('plan'));}$A->search(['t.license_key','u.email','u.name','u.company'],$s->str('q'));$m=$A->paginate($this->pageNumber($s),25);$m['items']=License::castAll($m['items']);return $this->view('admin/licenses/index',['res'=>$m,'plans'=>Plan::all('sort'),'filters'=>['q'=>$s->str('q'),'status'=>$s->str('status'),'plan'=>$s->str('plan')],'meta'=>['title'=>t('admin.licenses')]]);}public function create(Request $a):Response{return $this->view('admin/licenses/create',['plans'=>Plan::all('sort'),'meta'=>['title'=>t('admin.license_create')]]);}public function store(Request $c):Response{if($q=$this->validate($c,['email'=>'required|email','plan'=>'required','months'=>'required|int|min:1|max:120','max_activations'=>'required|int|min:1|max:100'],'/admin/licenses/create')){return $q;}$W=Plan::findBySlug($c->str('plan'));$E=User::findByEmail($c->str('email'));if(!$W){$this->flash('error',t('checkout.plan_unavailable'));return $this->redirect('/admin/licenses/create');}if(!$E){$r=bin2hex(random_bytes(8));$b=User::register($c->str('email'),$r,$c->str('name')?:$c->str('email'),lang());$E=User::find($b);try{(new Mailer())->sendTemplate($E['email'],'welcome',['user'=>$E,'password'=>$r,'verify_url'=>null],lang(),$E['name']);}catch(\Throwable){}}$g=['max_activations'=>$c->int('max_activations',1),'notes'=>$c->str('notes')?:null];if($c->str('max_cameras')!==''){$g['max_cameras']=$c->int('max_cameras');}$i=LicenseService::create((int)$E['id'],$W,$c->int('months')>=12?'year':'month',null,$c->int('months'),$g);if($c->bool('send_mail')){try{(new Mailer())->sendTemplate($E['email'],'order_confirmation',['user'=>$E,'order'=>null,'license'=>$i,'plan'=>$W,'invoice'=>null],$E['lang']?:'fr',$E['name']);}catch(\Throwable){}}$this->flash('success',t('admin.license_created').' '.$i['license_key']);return $this->redirect('/admin/licenses/'.$i['id']);}public function show(Request $a,string $i):Response{$c=License::withPlan((int)$i);if(!$c){return $this->redirect('/admin/licenses');}return $this->view('admin/licenses/show',['license'=>$c,'activations'=>License::activations((int)$c['id']),'events'=>License::events((int)$c['id'],100),'plans'=>Plan::all('sort'),'meta'=>['title'=>$c['license_key']]]);}public function action(Request $w,string $T):Response{$V=License::find((int)$T);if(!$V){return $this->redirect('/admin/licenses');}$J=$w->str('action');$j=$w->str('reason');switch($J){case'suspend':case'revoke':case'activate':LicenseService::setStatus($V,$J==='activate'?'active':($J==='suspend'?'suspended':'revoked'),$j);if($J==='activate'&&License::isExpired($V)){LicenseService::extend($V,1);}break;case'extend':LicenseService::extend($V,max(1,$w->int('months',1)));break;case'set_expiry':$O=strtotime($w->str('expires_at'));if($O){License::update((int)$V['id'],['expires_at'=>gmdate('Y-m-d 23:59:59',$O),'status'=>$O>time()&&$V['status']==='expired'?'active':$V['status']]);License::logEvent((int)$V['id'],'expiry_set',['expires_at'=>gmdate('Y-m-d',$O)]);}break;case'max_activations':License::update((int)$V['id'],['max_activations'=>max(1,$w->int('max_activations',1))]);License::logEvent((int)$V['id'],'max_activations',['value'=>$w->int('max_activations',1)]);break;case'change_plan':$L=Plan::findBySlug($w->str('plan'));if($L){LicenseService::changePlan($V,$L,$V['period'],null,false);}break;case'revoke_activation':LicenseService::revokeActivation($w->int('activation_id'),(int)$V['id'],'admin');break;case'notes':License::update((int)$V['id'],['notes'=>$w->str('notes')?:null]);break;}AuditLog::log('admin.license_'.$J,$V['license_key'],['reason'=>$j]);$this->flash('success',t('common.saved'));return $this->redirect('/admin/licenses/'.$T);}}